	// R| 		if (is.na(legend.settings.landscape$item.r)) legend.settings.landscape$item.r = r
	// R| 		if (is.na(legend.settings.portrait$item.r)) legend.settings.portrait$item.r = r
	// R|
	// R| 		outer.margins = rep(outer.margins, length.out = 4)
