	// R| 				# 		to <- ad$hdist
	// R| 				# 	} else {
	// R| 				# 		to <- as.numeric(units::set_units(units::set_units(1, attr(ad$hdist, "units")$numerator, mode = "standard"), units::as_units(unit), mode = "standard"))
	// R| 				# 	}
	// R| 				# }
	// R|
	// R| 				dst = distances_bbox_sides(bbx)
	// R|
	// R| 				if (o$unit %in% c("metric", "imperial")) {
	// R| 					# automatic
	// R|
	// R| 					uns = if (o$unit == "metric") c("km", "m", "mm") else c("mi", "yd", "ft", "in")
	// R| 					res = vapply(uns, function(u) {
	// R| 						as.numeric(units::set_units(dst[2], units::as_units(u), mode = "standard"))
	// R| 					}, FUN.VALUE = numeric(1))
	// R|
	// R| 					if (is.na(res[2])) {
	// R| 						unit = uns[1]
	// R| 					} else {
	// R| 						res_num = as.numeric(res)
	// R| 						if (any(res_num >= 10)) {
	// R| 							unit = names(res)[res_num >= 10][1]
	// R| 						} else {
	// R| 							unit = tail(names(res), 1)
	// R| 						}
	// R| 					}
	// R| 				} else {
	// R| 					unit = o$unit
	// R| 				}
	// R|
	// R| 				units::set_units(dst, units::as_units(unit), mode = "standard")
	// R| 				list(projection=crs, unit=unit, dst = dst, projected = !longlat)
	// R| 			}
	// R| 		})]
	// R|
	// R| 		# determine automatic position of inside comp
	// R| 		if (!any(o$free.coords) && any(cdt$class == "autoin")) {
	// R| 			shp = tmain[[1]]$shpDT$shpTM[[1]]$shp
	// R| 			# TODO take into account multiple main shapes
	// R| 			# TODO take use areas instead of coordinates for polygons
	// R| 			if (inherits(shp, c("sf", "sfc"))) {
