	// R| 										   legW = 0,
	// R| 										   legH = 0)
	// R| 				}, o$panel.labels[[1]], seq_len(o$fn[1]), SIMPLIFY = FALSE)))
	// R| 			}
	// R| 			o$panel.type = "none"
	// R| 		}
	// R|
	// R| 		o$ng = length(tmx)
	// R|
	// R| 		# determine row and col ids
	// R|
	// R| 		if (o$type == "grid") {
	// R| 			d[, row := as.integer((i - 1) %% o$nrows + 1)]
	// R| 			d[, col := as.integer((((i - 1) %/% o$nrows + 1) - 1) %% o$ncols + 1)]
	// R| 			d[, page := as.integer(i - 1) %/% (o$nrows * o$ncols) + 1]
	// R| 		} else {
	// R|
	// R| 			# wrap
	// R| 			if (o$nby[3] == 1L) {
	// R| 				if (!o$byrow) {
	// R| 					d[, row := as.integer((i - 1) %% o$nrows + 1)]
	// R| 					d[, col := as.integer((((i - 1) %/% o$nrows + 1) - 1) %% o$ncols + 1)]
	// R| 				} else {
	// R| 					d[, col := as.integer((i - 1) %% o$ncols + 1)]
	// R| 					d[, row := as.integer((((i - 1) %/% o$ncols + 1) - 1) %% o$nrows + 1)]
	// R| 				}
	// R| 				d[, page := as.integer(i - 1) %/% (o$nrows * o$ncols) + 1]
	// R| 			} else {
	// R| 				d[, j:= rep(1L:o$npp, length.out = nrow(d))]
	// R| 				if (!o$byrow) {
	// R| 					d[, row := as.integer((j - 1) %% o$nrows + 1)]
	// R| 					d[, col := as.integer((((j - 1) %/% o$nrows + 1) - 1) %% o$ncols + 1)]
	// R| 				} else {
	// R| 					d[, col := as.integer((j - 1) %% o$ncols + 1)]
	// R| 					d[, row := as.integer((((j - 1) %/% o$ncols + 1) - 1) %% o$nrows + 1)]
	// R| 				}
	// R| 				d[, page := by3]
	// R| 				d[, j:= NULL]
	// R| 			}
	// R| 		}
	// R|
	// R| 	}
	// R|
	// R|
	// R|
	// R| 	#####o$legend.autoin.pos = c("left", "top")
	// R|
	// R| 	# prepare function names
	// R| 	FUNinit = paste0("tmap", gs, "Init")
	// R| 	FUNaux = paste0("tmap", gs, "Aux")
	// R| 	FUNrun = paste0("tmap", gs, "Run")
	// R| 	FUNshape = paste0("tmap", gs, "Shape")
	// R| 	FUNoverlay = paste0("tmap", gs, "Overlay")
	// R| 	FUNwrap = paste0("tmap", gs, "Wrap")
	// R| 	FUNxtab = paste0("tmap", gs, "Xtab")
	// R|
	// R| 	FUNxlab = paste0("tmap", gs, "Xlab")
	// R| 	FUNylab = paste0("tmap", gs, "Ylab")
	// R|
	// R|
	// R| 	FUNgridxlab = paste0("tmap", gs, "GridXLab")
	// R| 	FUNgridylab = paste0("tmap", gs, "GridYLab")
	// R|
	// R| 	# for inset maps
	// R| 	inset_frame_ids = if (nrow(cdt) == 0L) integer(0) else which(sapply(cdt$comp, function(cmp) "bbox" %in% names(cmp)))
	// R|
	// R| 	if (!o$legend.only) {
	// R| 		# create table with bounding boxes (the only important property, apart from settings)
	// R| 		db = data.table(bbox = unique(d$bbox[!is.na(d$asp)]))
	// R| 		db[, i:=1L:nrow(db)]
	// R| 		d[, bi:=db$i[match(d$bbox, db$bbox)]]
	// R|
	// R| 		## process components
	// R| 		if (nrow(cdt)) cdt = process_components2(cdt, o)
	// R|
	// R| 		# init
	// R| 		res = do.call(FUNinit, c(list(o = o, show = show, newpage = newpage, return.asp = return.asp, vp = vp, prx = prx), args))
	// R| 		if (return.asp) {
	// R| 			return(res)
	// R| 		} else {
	// R| 			.TMAP$geo_ref = get_geo_ref(bbx = db$bbox[[1]],
	// R| 										crs = crs,
	// R| 										inner_margins = o$inner.margins,
	// R| 										dev_size = res$dev[1:2], map_size = res$map[1:2], offset = res$margins)
	// R| 			.TMAP$animation = list(fps = o$fps, play = o$play)
	// R| 		}
	// R|
	// R| 		## prepare aux layers
	// R| 		if (length(aux)) {
	// R| 			# prepare aux layers and return group label (in case it is not user specified)
	// R| 			aux_group_def = mapply(function(a, id) {
	// R| 				FUNaux_prep = paste0("tmap", gs, "AuxPrepare")
	// R| 				a_args = structure(a$args, class = c(a$mapping.fun, "list"))
	// R|
	// R| 				do.call(FUNaux_prep, list(a = a_args, bs = db$bbox, id = id, o = o))
	// R| 			}, aux, 1:length(aux))
	// R| 			aux_group = mapply(function(a, agd) {
	// R| 				ng = lengths(gregexpr("__", agd, fixed = TRUE))
	// R| 				if (is.na(a$group)) agd else as.character(a$group)
	// R| 			}, aux, aux_group_def, USE.NAMES = FALSE)
	// R|
	// R| 			aux_group.control = vapply(aux, function(a) {
	// R| 				a$group.control
	// R| 			}, FUN.VALUE = character(1))
	// R|
	// R| 			# find lid (layer plot id values) for aux layers
	// R| 			aux_lid = vapply(aux, function(a) a$lid, FUN.VALUE = numeric(1))
	// R| 		}
	// R|
	// R| 		if (!any_data_layer && !length(aux)) {
	// R| 			message_nothing_to_show(any_groups)
	// R| 			return(invisible(NULL))
	// R| 		}
	// R|
	// R|
	// R|
	// R| 		# data frame for layer ids
	// R| 		q = do.call(rbind, c(
	// R| 			{if (any_data_layer) {
	// R| 				lapply(1L:o$ng, function(ig) {
	// R| 					tmxi = tmx[[ig]]
	// R| 					nl = length(tmxi$layers)
	// R| 					lid = vapply(tmxi$layers, function(l) {l$lid}, FUN.VALUE = numeric(1))
	// R| 					group = vapply(tmxi$layers, function(l) {l$group}, FUN.VALUE = character(1))
	// R| 					group.control = vapply(tmxi$layers, function(l) {l$group.control}, FUN.VALUE = character(1)) # used to determine control layer group (view mode)
	// R| 					data.frame(gid = rep(ig, nl), g_lid = 1:nl, lid = unname(lid), group = unname(group), group.control = unname(group.control), lid2 = rep(0, nl), pane = rep("", nl), new = rep(TRUE, nl), group.zoom_levels = I(rep(list(NA),nl)))
	// R| 				})
	// R| 			} else {
	// R| 				NULL
	// R| 			}},
	// R| 			{if (length(aux)) list(data.frame(gid = 0, g_lid = 1L:length(aux), lid = unname(aux_lid), group = unname(aux_group), group.control = unname(aux_group.control), lid2 = 0, pane = "", new = TRUE, group.zoom_levels = I(rep(list(NA),length(aux))))) else NULL}))
	// R|
	// R| 		#q$lid[q$lid != 0] = q$lid[q$lid != 0] + 400L
	// R|
	// R| 		if (.TMAP$proxy) {
	// R| 			q0 = .TMAP$q
	// R| 			q0$new = FALSE
	// R| 			q = rbind(q0, q)
	// R| 		}
	// R|
	// R| 		qnotnull = (q$lid != 0)
	// R| 		if (any(qnotnull)) q$lid2[qnotnull] = rank(q$lid[qnotnull])
	// R|
	// R| 		q = q[order(q$lid2), ]
	// R| 		q$pane = "tilePane"
	// R|
	// R| 		q$pane[q$lid2 > 0] = pane_name(q$lid[q$lid2 > 0])
	// R|
	// R| 		# via tm_group, control and zoom levels can be set
	// R| 		# these are stored in tmap options view_group_{name}, and merged with q:
	// R| 		og = o[substr(names(o), 1, 10) == "view_group"]
	// R| 		ogdf = 	data.frame(name = vapply(og, "[[",FUN.VALUE = character(1), "name", USE.NAMES = FALSE),
	// R| 						   control = vapply(og, function(x) {
	// R| 						   	as.character(x[["control"]])
	// R| 						   } , FUN.VALUE = character(1), USE.NAMES = FALSE),
	// R| 						   zoom_levels = I(unname(lapply(og, "[[", "zoom_levels"))))
	// R| 		q$group.control = mapply(function(gi, v) {
	// R| 			id = which(ogdf$name == gi)
	// R| 			if (!length(id)) return(v)
	// R| 			v2 = ogdf$control[id]
	// R| 			if (is.na(v2)) return(v) else return(v2)
	// R| 		}, q$group, q$group.control, USE.NAMES = FALSE, SIMPLIFY = TRUE)
	// R| 		q$group.zoom_levels = mapply(function(gi, v) {
	// R| 			id = which(ogdf$name == gi)
	// R| 			if (!length(id)) return(NA)
	// R| 			return(ogdf$zoom_levels[[id]])
	// R| 		}, q$group, q$group.control, USE.NAMES = FALSE, SIMPLIFY = FALSE)
	// R| 		q$group.control[!is.na(q$group.zoom_levels)] = "none" # see leaflet::groupOptions
	// R|
	// R|
	// R|
	// R| 		# q data frame:
	// R| 		# gid = tmap-group counter
	// R| 		# g_lid = layer counter inside tmap-group
	// R| 		# lid = possibly-user-defined layer order number
	// R| 		# lid2 = same as lid, but 1,2,3,...
	// R| 		# pane = pane name (for view mode)
	// R| 		# group = group name (for selecting layers in view mode)
	// R| 		# group.control = leaflet::addLayerControl: check, radio or none (view mode)
	// R| 		# group.zoom_levels = leaflet::groupOptions: zoom levels displayed at
	// R|
	// R| 		do.call(FUNaux, list(o = o, q = q))
	// R|
	// R|
	// R| 		# plot xtab headers
	// R| 		if (o$panel.type == "xtab") {
	// R| 			for (k in 1:o$npages) {
	// R| 				labrows = o$panel.labels[[1]]
	// R| 				labcols = o$panel.labels[[2]]
	// R| 				if (length(labrows) == o$nrows) for (i in 1:o$nrows) do.call(FUNxtab, list(label = labrows[i], facet_row = i, facet_page = k, o = o))
	// R| 				if (length(labcols) == o$ncols) for (j in 1:o$ncols) do.call(FUNxtab, list(label = labcols[j], facet_col = j, facet_page = k, o = o))
	// R|
	// R| 			}
	// R| 		}
	// R|
	// R|
	// R| 		# plot xlab and ylab
	// R| 		if (o$xlab.show) {
	// R| 			for (k in 1:o$npages) {
	// R| 				do.call(FUNxlab, list(facet_page = k, o = o))
	// R| 			}
	// R| 		}
	// R| 		if (o$ylab.show) {
	// R| 			for (k in 1:o$npages) {
	// R| 				do.call(FUNylab, list(facet_page = k, o = o))
	// R| 			}
	// R| 		}
	// R|
	// R|
	// R|
	// R| 		for (i in seq_len(nrow(d))) {
	// R| 			bbx = d$bbox[[i]]
	// R| 			if (o$panel.type == "wrap") do.call(FUNwrap, list(label = o$panel.labels[[o$panel.labels.dim]][d[[paste0("by", o$panel.labels.dim_data)]][i]], facet_row = d$row[i], facet_col = d$col[i], facet_page = d$page[i], o = o))
	// R| 			if (is.na(d$asp[i])) next
	// R| 			do.call(FUNshape, list(bbx = bbx, facet_row = d$row[i], facet_col = d$col[i], facet_page = d$page[i], o = o))
	// R|
	// R| 			# plot grid labels
	// R| 			if (o$grid.show && !o$grid.labels.inside_frame) {
	// R| 				if (o$grid.labels.show[2] && ((o$grid.labels.pos[1] == "left" && d$col[i] == 1) || (o$grid.labels.pos[1] == "right" && d$col[i] == o$ncols))) {
	// R| 					do.call(FUNgridylab, list(bi = d$bi[i], bbx = bbx, facet_row = d$row[i], facet_col = d$col[i], facet_page = d$page[i], o = o))
	// R| 				}
	// R| 				if (o$grid.labels.show[1] && ((o$grid.labels.pos[2] == "top" && d$row[i] == 1) || (o$grid.labels.pos[2] == "bottom" && d$row[i] == o$nrows))) {
	// R| 					do.call(FUNgridxlab, list(bi = d$bi[i], bbx = bbx, facet_row = d$row[i], facet_col = d$col[i], facet_page = d$page[i], o = o))
	// R| 				}
	// R| 			}
	// R|
	// R| 			for (qi in which(q$new)) {
	// R| 				gid = q$gid[qi]
	// R| 				g_lid = q$g_lid[qi]
	// R| 				pane = q$pane[qi]
	// R| 				group = q$group[qi]
	// R| 				if (gid > 0) {
	// R| 					# data layer
	// R| 					bl = tmx[[gid]]$layers[[g_lid]]
	// R| 					shpTM = get_shpTM(bl$shpDT, d$by1[i], d$by2[i], d$by3[i])[[1]]
	// R| 					mdt = get_dt(bl$mapping_dt, d$by1[i], d$by2[i], d$by3[i])
	// R|
	// R| 					id = paste0("f", sprintf("%03d", i), "g", sprintf("%02d", gid), "l", sprintf("%02d", g_lid))
	// R|
	// R| 					if (nrow(mdt) != 0) {
	// R| 						gp = bl$gp
	// R|
	// R| 						FUN = paste0("tmap", gs, "DataPlot")
	// R|
	// R| 						a = structure(bl$mapping_args, class = c(bl$mapping_fun, "list"))
	// R|
	// R| 						do.call(FUN, c(list(a = a, shpTM = shpTM, dt = mdt, pdt = bl$popup.data, popup.format = bl$popup.format, ptdt = bl$popup.title.data, popup.layout = bl$popup.layout, hdt = bl$hover.data, idt = bl$id.data, gp = gp, bbx = bbx, facet_col = d$col[i], facet_row = d$row[i], facet_page = d$page[i], id = id, pane = pane, group = group, glid = bl$glid, o = o)))
	// R| 					}
	// R|
	// R| 				} else {
	// R| 					g_lid = q$g_lid[qi]
	// R|
	// R|
	// R| 					# aux layer
	// R| 					a = aux[[g_lid]]
	// R| 					a_args = structure(a$args, class = c(a$mapping.fun, "list"))
	// R|
	// R| 					FUNaux_plot = paste0("tmap", gs, "AuxPlot")
	// R|
	// R| 					id = g_lid # to do: test!
	// R| 					do.call(FUNaux_plot, list(a = a_args, bi = d$bi[i], bbx = bbx, facet_col = d$col[i], facet_row = d$row[i], facet_page = d$page[i], id = id, pane = pane, group = group, o = o))
	// R|
	// R| 				}
	// R|
	// R|
	// R|
	// R| 			}
	// R|
	// R| 			# inset map frame
	// R| 			if (length(inset_frame_ids)) {
	// R| 				sfc_bbxs = do.call(c, lapply(inset_frame_ids, function(iid) {
	// R| 					ic = cdt$comp[[iid]]
	// R| 					sf::st_transform(tmaptools::bb_poly(ic$bbox), crs = crs)
	// R| 				}))
	// R|
	// R| 				collect_properties = function(comps, props) {
	// R| 					res = lapply(props, function(p) {
	// R| 						sapply(comps, function(cmp) {
	// R| 							cmp[[p]]
	// R| 						})
	// R| 					})
	// R| 					names(res) = props
	// R| 					res
	// R| 				}
	// R|
	// R| 				prp = collect_properties(cdt$comp[inset_frame_ids],
	// R| 										 c("box_frame", "box_frame.color", "box_frame.alpha", "box_frame.lwd", "box_frame.lty", "box_bg", "box_bg.color", "box_bg.alpha"))
	// R| 				calld = lapply(cdt$comp[inset_frame_ids], function(cmp) cmp$called)
	// R|
	// R| 				prp$box_frame[vapply(calld, function(cl) "box_frame.color" %in% cl, FUN.VALUE = logical(1))] = TRUE
	// R| 				prp$box_bg[vapply(calld, function(cl) "box_bg.color" %in% cl, FUN.VALUE = logical(1))] = TRUE
	// R|
	// R| 				prp$box_bg.color[!prp$box_bg] =  "#00000000"
	// R| 				prp$box_frame.color[!prp$box_frame] =  "#00000000"
	// R|
	// R|
	// R| 				tb = tm_polygons()[[1]]
	// R|
	// R|
	// R| 				gp = tb$gpar
	// R|
	// R| 				FUN = paste0("tmap", gs, "DataPlot")
	// R|
	// R| 				a = structure(tb$mapping.args, class = c("tm_data_polygons", "list"))
	// R|
	// R| 				shapepTM = shapeTM(sfc_bbxs, tmapID = seq_along(sfc_bbxs))
	// R|
	// R| 				shpTM = tmapTransPolygons(shapepTM, args = tb$trans.args, plot.order = tb$plot.order)
	// R|
	// R| 				mdt = data.table(tmapID__ = seq_along(sfc_bbxs), fill = prp$box_bg.color, col = prp$box_frame.color, lwd = prp$box_frame.lwd, lty = prp$box_frame.lty, fill_alpha = prp$box_bg.alpha, col_alpha = prp$box_frame.alpha, ord__ = 1L)
	// R|
	// R| 				do.call(FUN, c(list(a = a, shpTM = shpTM, dt = mdt, pdt = NULL, popup.format = list(), hdt = NULL, idt = NULL, gp = gp, bbx = bbx, facet_col = d$col[i], facet_row = d$row[i], facet_page = d$page[i], id = "inset_frame", pane = "tmap500", group = NA, o = o)))
	// R|
	// R| 			}
	// R| 			do.call(FUNoverlay, list(bbx = bbx, facet_row = d$row[i], facet_col = d$col[i], facet_page = d$page[i], o = o))
	// R| 		}
	// R|
	// R| 	} else {
	// R| 		# init
	// R| 		asp = do.call(FUNinit, list(o = o, return.asp = return.asp, vp = vp))
	// R| 	}
	// R|
	// R|
	// R| 	if (o$legend.only) {
	// R| 		cdt[, facet_row := "1"]
	// R| 		cdt[, facet_col := "1"]
	// R| 		cdt[, page := 1L]
	// R| 		cdt[, bbox := list()]
	// R| 	} else {
	// R| 		is_in = cdt$class == "in"
	// R| 		#is_in = rep(TRUE, nrow(cdt))
	// R| 		if (any(is_in)) {
	// R| 			legs_in = lapply(which(is_in), function(i) {
	// R| 				d2 = data.table::copy(d)
	// R| 				legsi = cdt[i, ]
	// R| 				if (o$type != "grid" && o$nrows == 1) {
	// R| 					# reverse above
	// R| 					d2[, by2 := by1]
	// R| 					d2[, by1 := 1]
	// R| 				}
	// R|
	// R| 				if (is.na(legsi$by1__)) d2[, by1:= NA]
	// R| 				if (is.na(legsi$by2__)) d2[, by2:= NA]
	// R| 				if (is.na(legsi$by3__)) d2[, by3:= NA]
	// R| 				legsi = merge(legsi, d2[, c("by1", "by2", "by3", "row", "col", "page", "bbox", "units"), with = FALSE], by.x = c("by1__", "by2__", "by3__"), by.y = c("by1", "by2", "by3"))
	// R| 				legsi[, ':='(facet_row = as.character(row), facet_col = as.character(col), row = NULL, col = NULL)]
	// R| 				legsi
	// R| 			})
	// R| 		} else {
	// R| 			legs_in = NULL
	// R| 		}
	// R|
	// R|
	// R| 		legs_out = copy(cdt[!is_in])
	// R| 		if (nrow(legs_out) >= 1L) {
	// R| 			legs_out[, page:=NA_integer_]
	// R| 			legs_out[!is.na(by3__), page := by3__]
	// R|
	// R| 			by1_clip =  (length(which(legs_out$by1__ > o$nrows)) > 0L) && all(legs_out$facet_row == legs_out$by1__)
	// R| 			by2_clip =  (length(which(legs_out$by2__ > o$ncols)) > 0L) && all(legs_out$facet_col == legs_out$by2__)
	// R| 			if (by1_clip && by2_clip) {
	// R| 				cli::cli_abort("multiple pages cannot be created over two facet dimensions")
	// R| 			}
	// R| 			if (by1_clip) {
	// R| 				legs_out[!is.na(by1__), ':='(page = ((by1__-1L) %/% o$nrows) + 1L, facet_row = ((by1__-1L) %% o$nrows) + 1L)]
	// R| 			} else if (by2_clip) {
	// R| 				legs_out[!is.na(by2__), ':='(page = ((by2__-1L) %/% o$ncols) + 1L, facet_col = ((by2__-1L) %% o$ncols) + 1L)]
	// R| 			}
	// R|
	// R| 			# ad-hoc method: take first bbox and units
	// R| 			bbox_nb = d$bbox[1]
	// R| 			attr(bbox_nb, "borrow") = list(col = d$col[1], row = d$row[1])
	// R| 			legs_out[, bbox:=list(bbox_nb)]
	// R| 			legs_out[, units:=list(d$units[1])]
	// R| 		} else {
	// R| 			legs_out$page = integer()
	// R| 			legs_out$bbox = list()
	// R| 			legs_out$units = list()
	// R| 		}
	// R|
	// R|
	// R|
	// R| 		cdt = data.table::rbindlist(c(list(legs_out), legs_in))
	// R|
	// R| 		cdt$comp = mapply(function(cmp, bbx, u) {
	// R| 			if (!("bbox" %in% names(cmp))) cmp$bbox = bbx
	// R| 			cmp$units = u
	// R| 			cmp
	// R| 		}, cdt$comp, cdt$bbox, cdt$units, SIMPLIFY = FALSE)
	// R|
	// R| 		leg_dummy = tm_legend_hide()
	// R| 		leg_dummy$active = FALSE
	// R| 		leg_dummy$vneutral = NA
