const rtdal009246Source0001 = `tm_crs = function(crs = NA, property = NA, bbox = NULL, ...) {
	bb_args = list(...)
	if (is.na(crs)) {
		if (is.na(property)) {
			return(tm_options(bbox = bbox, bbox_args = bb_args))
		} else {
			crs = "auto"
		}
	}
	if (identical(crs, "auto") && !is.na(property)) {
		if (!(property %in% c("global", "area", "distance", "shape"))) {
			message_crs_property_unknown()
		}
		extra = property
	} else {
		extra = ""
	}

	if (is.character(crs) && crs %in% c("laea", "aeqd", "utm", "pconic", "eqdc")) {
		extra = crs
		crs = "auto"
	}

	tm_options(crs = crs, crs_extra = extra, bbox = bbox, bbox_args = bb_args)
}`

const rtdal009246Source0002 = `consider_global = function(x, th = 0.6) {
	b = sf::st_bbox(x)
	# in case margins are applied
	if (sf::st_is_longlat(b)) {
		b["xmin"] = max(b["xmin"], -180)
		b["xmax"] = min(b["xmax"], 180)
		b["ymin"] = max(b["ymin"], -90)
		b["ymax"] = min(b["ymax"], 90)
	}
	if (b$xmin == b$xmax || b$ymin == b$ymax) return(FALSE)
	earth_surface = 5.1e14
	area = b |>
		sf::st_as_sfc() |>
		sf::st_area() |>
		as.numeric()
	area > (earth_surface * 0.6)
}`

const rtdal009246Source0003 = `auto_crs = function(x, crs_extra, crs_global) {

	if (identical(x, TRUE)) return(crs_global)




    # check if global should be used
	is_global = if (crs_extra == "global") {
		TRUE
	} else if (crs_extra != "") {
		FALSE
	} else {
		consider_global(x)
	}

	y = if (is_global) {
		crs_global
	} else {
		# impute family
		proj = switch(crs_extra,
			area = "laea",
			distance = "aeqd",
			shape = "stere",
			aeqd = "aeqd",
			utm = "utm",
			pconic = "pconic",
			eqdc = "eqdc",
			stere = "stere",
			"laea"
		)
		to_generic_projected(x, proj = proj, return_as = "crs")
	}
	sf::st_crs(y)
}`

const rtdal009246Source0004 = "to_generic_projected <- function(\n\t\tx,\n\t\tproj = c(\"laea\", \"aeqd\", \"utm\", \"pconic\", \"eqdc\", \"stere\"),\n\t\tellps = \"WGS84\",\n\t\tno_defs = TRUE,\n\t\topts = \"\",\n\t\treturn_as = c(\"sf\", \"proj4\", \"wkt\", \"crs\")) {\n\t# arg assertions\n\tif (!rlang::is_true(rlang::inherits_any(x, c(\"sf\", \"sfc\", \"stars\")))) {\n\t\trlang::abort(\n\t\t\t\"`x` must be either an sf object or an sfc object or a stars object\",\n\t\t\tclass = \"to_generic_projected_incorrect_input\"\n\t\t)\n\t}\n\n\tproj <- rlang::arg_match(proj)\n\tellps <- rlang::arg_match(ellps, sf::sf_proj_info(type = \"ellps\")$name)\n\n\tif (!rlang::is_logical(no_defs)) {\n\t\trlang::abort(\"`no_defs` must be a logical value\",\n\t\t\t\t\t class = \"to_generic_projected_incorrect_input\"\n\t\t)\n\t}\n\n\tif (!rlang::is_character(opts) && !nchar(opts)) {\n\t\trlang::abort(\"`opts` must be a character vector\",\n\t\t\t\t\t class = \"to_generic_projected_incorrect_input\"\n\t\t)\n\t}\n\n\treturn_as <- rlang::arg_match(return_as)\n\n\t# was centroid\n\tcent_coor <- sf::sf_project(\n\t\tsf::st_crs(x), \"EPSG:4326\",\n\t\tsf::st_bbox(x) |>\n\t\t\tsf::st_as_sfc() |>\n\t\t\tsf::st_centroid() |>\n\t\t\tsf::st_coordinates()\n\t)\n\n\t# configure proj args\n\tn_or_s <- ifelse(cent_coor[2] == 0, \"\",\n\t\t\t\t\t ifelse(cent_coor[2] > 0, \"+north\", \"+south\")\n\t)\n\n\tno_defs <- ifelse(no_defs, \"+no_defs\", \"\")\n\n\tif (proj %in% c(\"pconic\", \"eqdc\")) {\n\t\tbounds <- sf::st_bbox(sf::st_transform(x, 4326))\n\t\tlat_1 <- bounds$ymax\n\t\tlat_2 <- bounds$ymin\n\t}\n\n\t# base R replacement of glue::glue to reduce dependencies\n\tglue = function(..., .sep) {\n\t\targs = list(...)\n\t\tpaste(lapply(args, gluestick, src = parent.frame()), collapse = .sep)\n\t}\n\n\n\t# construct proj4 string\n\tprj <- trimws(switch(proj,\n\t\t\t\t\t\t laea = glue(\n\t\t\t\t\t\t \t\"+proj=laea +lon_0={cent_coor[1]} +lat_0={cent_coor[2]}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t ),\n\t\t\t\t\t\t utm = glue(\n\t\t\t\t\t\t \t\"+proj=utm +zone={round((180 + cent_coor[1]) / 6)} {n_or_s}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t ),\n\t\t\t\t\t\t aeqd = glue(\n\t\t\t\t\t\t \t\"+proj=aeqd +lon_0={cent_coor[1]} +lat_0={cent_coor[2]}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t ),\n\t\t\t\t\t\t pconic = glue(\n\t\t\t\t\t\t \t\"+proj=pconic +lon_0={cent_coor[1]} +lat_0={cent_coor[2]}\",\n\t\t\t\t\t\t \t\"+lat_1={lat_1} +lat_2={lat_2}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t ),\n\t\t\t\t\t\t eqdc = glue(\n\t\t\t\t\t\t \t\"+proj=eqdc +lon_0={cent_coor[1]}\",\n\t\t\t\t\t\t \t\"+lat_1={lat_1} +lat_2={lat_2}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t ),\n\t\t\t\t\t\t stere = glue(\n\t\t\t\t\t\t \t\"+proj=stere +lon_0={cent_coor[1]} +lat_0={cent_coor[2]}\",\n\t\t\t\t\t\t \t\"+ellps={ellps} {no_defs}\",\n\t\t\t\t\t\t \topts,\n\t\t\t\t\t\t \t.sep = \" \"\n\t\t\t\t\t\t )\n\t))\n\n\tswitch(return_as,\n\t\t   sf = sf::st_transform(x, prj),\n\t\t   proj4 = prj,\n\t\t   wkt = sf::st_crs(prj)$wkt,\n\t\t   crs = sf::st_crs(prj)\n\t)\n}"

const rtdal009246Source0005 = `gluestick <- function(fmt, src = parent.frame(), open = "{", close = "}", eval = TRUE) {

	nchar_open  <- nchar(open)
	nchar_close <- nchar(close)

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Sanity checks
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	stopifnot(exprs = {
		is.character(fmt)
		length(fmt) == 1L
		is.character(open)
		length(open) == 1L
		nchar_open > 0L
		is.character(close)
		length(close) == 1
		nchar_close > 0
	})

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Brute force the open/close characters into a regular expression for
	# extracting the expressions from the format string
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	open  <- gsub("(.)", "\\\\\\1", open ) # Escape everything!!
	close <- gsub("(.)", "\\\\\\1", close) # Escape everything!!
	re    <- paste0(open, ".*?", close)

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Extract the delimited expressions
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	matches  <- gregexpr(re, fmt)
	exprs    <- regmatches(fmt, matches)[[1]]

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Remove the delimiters
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	exprs <- substr(exprs, nchar_open + 1L, nchar(exprs) - nchar_close)

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# create a valid sprintf fmt string.
	#  - replace all "{expr}" strings with "%s"
	#  - escape any '%' so sprintf() doesn't try and use them for formatting
	#    but only if the '%' is NOT followed by an 's'
	#
	# gluestick() doesn't deal with any pathological cases
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	fmt_sprintf <- gsub(re      , "%s", fmt)
	fmt_sprintf <- gsub("%(?!s)", "%%", fmt_sprintf, perl=TRUE)

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Evaluate
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	if (eval) {
		args <- lapply(exprs, function(expr) {eval(parse(text = expr), envir = src)})
	} else {
		args <- unname(mget(exprs, envir = as.environment(src)))
	}

	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	# Create the string(s)
	#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
	do.call(sprintf, c(list(fmt_sprintf), args))
}`

