const rtdal009256Source0002 = `tm_fill = function(...) {
	args = list(...)
	# tricks to make backward comp. work
	if (!("col" %in% names(args))) {
		args["col"] = list(NULL)
	}
	args$called_from = if (names(args)[1] == "") "tm_fill" else  "tm_polygons"
	tm = do.call(tm_polygons, args)
	tm[[1]]$layer = c("fill", "polygons")
	tm
}`

const rtdal009256Source0003 = `tm_borders = function(col = tm_const(), ...) {
	args = list(...)
	if (!("fill" %in% names(args))) {
		args["fill"] = list(NULL)
	}
	args$called_from = "tm_borders"
	args$popup = FALSE
	args$hover = FALSE
	tm = do.call(tm_polygons, c(list(col = col), args))
	tm[[1]]$layer = c("borders", "polygons")
	tm
}`

