	// R| 	})
	// R|
	// R| 	nr = length(rows)
	// R| 	nc = length(cols)
	// R|
	// R| 	cols_facet_ids = 1:o$ncols * 6 + 6
	// R| 	rows_facet_ids = 1:o$nrows * 6 + 6
	// R|
	// R| 	#if (o$panel.type == "xtab") {
	// R| 	cols_panel_col_ids = cols_facet_ids
	// R| 	cols_panel_row_id = ifelse(o$panel.xtab.pos[2] == "top", 6, nc - 5)
	// R|
	// R| 	rows_panel_row_ids = rows_facet_ids
	// R| 	rows_panel_col_id = ifelse(o$panel.xtab.pos[1] == "left", 6, nc - 5)
	// R| 	#} else if (o$panel.type == "wrap") {
	// R| 	cols_panel_ids = cols_facet_ids + ifelse(o$panel.wrap.pos  == "left", -2, ifelse(o$panel.wrap.pos  == "right", 2, 0))
	// R| 	rows_panel_ids = rows_facet_ids + ifelse(o$panel.wrap.pos  == "top", -2, ifelse(o$panel.wrap.pos  == "bottom", 2, 0))
	// R|
	// R| 	panel_col_rot = ifelse(o$panel.xtab.pos[2] == "top", o$panel.label.rot[2], o$panel.label.rot[4])
	// R| 	panel_row_rot = ifelse(o$panel.xtab.pos[1] == "left", o$panel.label.rot[1], o$panel.label.rot[3])
	// R| 	panel_rot = ifelse(o$panel.wrap.pos  == "left", o$panel.label.rot[1], ifelse(o$panel.wrap.pos  == "right", o$panel.label.rot[3], ifelse(o$panel.wrap.pos  == "top", o$panel.label.rot[2], o$panel.label.rot[4])))
