const rtdal009314Source0006 = `lty2dash = function(lty, lwd) {
	k = max(length(lty), length(lwd))
	lty = rep(lty, length.out = k)
	lwd = rep(lwd, length.out = k)



	tab = c(solid = "", dashed = "4 4", dotted = "1 3", dotdash = "1 3 4 3", longdash = "7 3", twodash = "2 2 6 2")
	are_words = (lty %in% names(tab))
	x = if (all(are_words)) {
		unname(tab[lty])
	} else {
		are_letters = (suppressWarnings(!is.na(as.numeric(lty))))

		if (!all(are_letters | are_words)) {
			stop("Incorrect lty specification: ", lty[which(!are_letters & !are_words)[1]])
		} else {
			lty[are_words] = unname(tab[lty[are_words]])
			lty[are_letters] = vapply(strsplit(lty[are_letters], ""), FUN = function(x) paste(x, collapse = " "), FUN.VALUE = character(1))
		}
		lty
	}

	# multiply by lwd
	split_x <- strsplit(x, " ")

	z = mapply(
		function(vals, mult) paste(as.numeric(vals) * mult, collapse = " "),
		split_x, lwd, USE.NAMES = FALSE
	)

	z[x == ""] = ""   # restore empties if needed
	z
}`

const rtdal009314Source0007 = "makeSymbolIcons2  = function (shape, color, fillColor = color, opacity, fillOpacity = opacity,\n\t\t  strokeWidth = 1, dashArray = \"none\", width, height = width, ...)\n{\n\tsymbols <- Map(leaflegend::makeSymbol, shape = shape, width = width,\n\t\t\t\t   height = height, color = color, fillColor = fillColor,\n\t\t\t\t   opacity = opacity, fillOpacity = fillOpacity, `stroke-width` = strokeWidth,\n\t\t\t\t   `stroke-dasharray` = dashArray,\n\t\t\t\t   ...)\n\tleaflet::icons(iconUrl = unname(symbols), iconAnchorX = width/2 + strokeWidth,\n\t\t\t\t   iconAnchorY = height/2 + strokeWidth)\n}"

const rtdal009314Source0008 = `split_alpha_channel <- function(x, alpha) {
	if (is.null(x)) {
		list(col=NULL, opacity=0)
	} else {
		RGBA <- col2rgb(x, alpha = TRUE)
		col <- rgb(RGBA[1,], RGBA[2,], RGBA[3,], maxColorValue = 255)
		opacity <- unname(RGBA[4,]/255 * alpha)
		list(col=col, opacity=opacity)
	}
}`

