const rtdal009316Source0004 = `tmapLeafletAuxPrepare.tm_aux_tiles = function(a, bs, id, o) {
	nms = names(a$server)
	a$server = unname(a$server)
	tiles = lapply(1L:length(bs), function(i) a)
	.TMAP_LEAFLET$tiles[[id]] = tiles
	if (!is.null(nms)) {
		paste0(nms, collapse = "__")
	} else {
		paste0(a$server, collapse = "__")
	}
}`

const rtdal009316Source0006 = `tmapLeafletAuxPlot.tm_aux_tiles = function(a, bi, bbx, facet_row, facet_col, facet_page, id, pane, group, o) {

	lf = get_lf(facet_row, facet_col, facet_page)

	rc_text = frc(facet_row, facet_col)


	tiles = .TMAP_LEAFLET$tiles[[id]][[bi]]

	if (o$credits.defined) {
		opt = leaflet::tileOptions(attribution = "", maxNativeZoom = tiles$max.native.zoom, pane = pane)
	} else {
		opt = leaflet::tileOptions(maxNativeZoom = tiles$max.native.zoom, pane = pane)
	}
	if (!is.na(o$set_zoom_limits[2])) opt$maxZoom = o$set_zoom_limits[2]

	k = length(tiles$server)

	groups = rep(strsplit(group, "__", fixed = TRUE)[[1]], length.out = k)

	for (i in 1L:k) {
		serv = tiles$server[i]
		if (serv != "") {
			if ((substr(serv, 1, 4) == "http")) {
				lf = leaflet::addTiles(lf, urlTemplate = serv, group = groups[i], options = opt)
			} else {
				# Invalid provider: warn and fall back to the default view basemap
				# rather than adding a broken (blank) provider layer, matching the
				# fallback behaviour of the maplibre/mapbox modes.
				if (!(serv %in% tmap_providers("view"))) {
					eq = basemap_equivalent(serv, "view")
					if (!is.na(eq)) {
						message_basemaps_equivalent(serv, "view", eq)
						serv = eq
					} else {
						message_basemaps_invalid_provider(serv, "view", o$basemap.server[1])
						serv = o$basemap.server[1]
					}
				}
				lf = leaflet::addProviderTiles(lf, provider = serv, group = groups[i], options = opt)
			}
		}
	}

	assign_lf(lf, facet_row, facet_col, facet_page)
	NULL
}`

const rtdal009316Source0008 = `tmapLeafletAuxPrepare.tm_aux_grid = function(a, bs, id, o) {

	grid_intervals = vapply(bs, function(b) {
		# implementation similarish as plot mode but needs polishing
		dx = b[3] - b[1]
		dy = b[4] - b[2]
		# if not specified, aim for 15 lines in total
		n.x = if (!is.na(a$n.x)) a$n.x else if (is.na(a$x)) 7.5 else length(a$x)
		n.y = if (!is.na(a$n.y)) a$n.y else if (is.na(a$y)) 7.5 else length(a$x)

		x = pretty30(b[c(1,3)], n=n.x, longlat = !is.na(a$crs) && sf::st_is_longlat(a$crs))
		y = pretty30(b[c(2,4)], n=n.y, longlat = !is.na(a$crs) && sf::st_is_longlat(a$crs))

		max((x[2] - x[1]), (y[2]-y[1]))
	}, FUN.VALUE = numeric(1))
	assign("grid_intervals", grid_intervals, envir = .TMAP_LEAFLET)

	return("grid")
}`

const rtdal009316Source0010 = `tmapLeafletAuxPlot.tm_aux_grid = function(a, bi, bbx, facet_row, facet_col, facet_page, id, pane, group, o) {
	lf = get_lf(facet_row, facet_col, facet_page)
	rc_text = frc(facet_row, facet_col)

	grid_intervals = get("grid_intervals", envir = .TMAP_LEAFLET)

	lf = leaflet::addGraticule(lf, interval = grid_intervals[bi], options = pathOptions(pane = pane))


	assign_lf(lf, facet_row, facet_col, facet_page)
	NULL
}`

