const rtdal009319Source0013 = `tmapLeafletCompWidth.tm_legend_landscape = function(comp, o) {
	within(comp, {
		if (type == "gradient") {
			width = if (is.na(width)) {
				# nitems set to 2 because labels are not supported yet
				get_legend_option(item.width, "gradient") * 2 * absolute_fontsize
			} else {
				if (width < 0) {
					-width
				} else {
					width * absolute_fontsize
				}
			}
		}
	})
}`

