	// R|
	// R| 			lf |>  leafgl::addGlPoints(shp2, fillColor = gp2$fillColor, radius = gp2$width, fillOpacity = gp2$fillOpacity[1], pane = pane, group = group, label = hdt, popup = popups, layerId = idt) %>%
	// R| 				assign_lf(facet_row, facet_col, facet_page)
	// R| 		} else {
	// R| 			# visible on-screen radius (leaflet px) = gp2$width * multiplier,
