const rtdal009345Source0001 = "make_by_vars = function(dt, tmf, smeta) {\n\tby123 = paste0(\"by\", 1L:3L)\n\tby123__ = paste0(\"by\", 1L:3L, \"__\")\n\twith(tmf, {\n\t\tif (length(b)) {\n\t\t\tfor (w in b) {\n\t\t\t\tbyvar = by123[w]\n\t\t\t\tbyname = by123__[w]\n\t\t\t\tvar = tmf[[byvar]]\n\n\t\t\t\tif (var == \"FRAME__\") {\n\t\t\t\t\tdt[, (byname):= NA_integer_] # dummy\n\t\t\t\t} else if (var %in% smeta$vars) {\n\t\t\t\t\tlevs = smeta$vars_levs[[var]]\n\t\t\t\t\tif (is.null(levs)) {\n\t\t\t\t\t\tcli::cli_abort(\"Variable {.val {var}} is used as facetting variable. Therefore, it should be a factor.\")\n\t\t\t\t\t}\n\t\t\t\t\tif (attr(levs, \"showNA\")) levs[length(levs)] = NA\n\n\t\t\t\t\t# `levs` are always character labels (built via as.character()\n\t\t\t\t\t# or levels() in get_fact_levels_na). match() does coerce the\n\t\t\t\t\t# left-hand side to character, but for classed columns it relies\n\t\t\t\t\t# on as.character() S3 dispatch: Date has an as.character method\n\t\t\t\t\t# and formats correctly, whereas POSIXct (and other date/time\n\t\t\t\t\t# classes lacking such a method) fall back to the raw underlying\n\t\t\t\t\t# double (e.g. \"1672574400\") and never match the formatted labels.\n\t\t\t\t\t# Coercing here with as.character() uses the same representation\n\t\t\t\t\t# that produced `levs`, so the join is correct for every class.\n\t\t\t\t\tdt[, (byname):= match(as.character(get(get(..byvar))), levs)]\n\t\t\t\t} else if (tmf[[byvar]] %in% smeta$dims) {\n\t\t\t\t\tdt[, (byname):= match(get(get(..byvar)), smeta$dims_vals[[var]])]\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t})\n\tinvisible(NULL)\n}"

const rtdal009345Source0002 = `get_fact_levels_na = function(x, o) {
	# POSIXlt is stored as a list; normalise to POSIXct so it is treated as a
	# date/time vector below instead of being caught by the is.list() guard
	if (inherits(x, "POSIXlt")) x = as.POSIXct(x)

	if (inherits(x, "sfc") || is.list(x) || is.expression(x)) {
		levs = NULL
	} else if (is.factor(x)) {
		if (o$drop.empty.facets) {
			tab = tabulate(x, nbins = nlevels(x))
			anyna = (sum(tab) != length(x)) # note that NA can already be included in the levels (in that case anyna = FALSE)
			levs = levels(x)[tab != 0]
		} else {
			anyna = anyNA(x)
			levs = levels(x)
		}

		if (!o$drop.NA.facets && anyna) {
			showNA = TRUE
			levs = c(levs, o$na.text)
		} else if (!o$drop.NA.facets && any(is.na(levs))) {
			showNA = TRUE
			levs[is.na(levs)] = o$na.text
		} else if (o$drop.NA.facets && any(is.na(levs))) {
			showNA = FALSE
			levs = levs[!is.na(levs)]
		} else {
			showNA = FALSE
		}
	} else if (inherits(x, c("POSIXct", "Date", "difftime"))) {
		# Date/time classes: keep the class. The plain branch below uses
		# as.vector(), which would strip the class and turn dates into raw
		# day/second counts. Order chronologically and format the labels with
		# the class's own as.character() method; make_by_vars() coerces the
		# column with the same as.character(), so the facet join lines up.
		u = unique(x)
		if (length(u) > o$facet_levels.max) {
			levs = NULL
		} else {
			levs = as.character(sort(u))
			if (!o$drop.NA.facets && any(is.na(u))) {
				showNA = TRUE
				levs = c(levs, o$na.text)
			} else {
				showNA = FALSE
			}
		}
	} else {
 		u = unique(as.vector(x))
		if (length(u) > o$facet_levels.max) {
			levs = NULL
		} else {
			levs = as.character(sort(u))
			if (!o$drop.NA.facets && any(is.na(u))) {
				showNA = TRUE
				levs = c(levs, o$na.text)
			} else {
				showNA = FALSE
			}
		}
	}
	if (!is.null(levs)) attr(levs, "showNA") = showNA
	levs
}`

