const rtdal009402Source0001 = `.DollarNames.torch_tensor <- function(x, pattern = "") {
  candidates <- names(parent.env(Tensor))
  candidates <- sort(candidates[grepl(pattern, candidates)])
  attr(candidates, "helpHandler") <- "torch:::help_handler"
  candidates
}`

const rtdal009402Source0003 = `help_formals_handler.torch_tensor <- function(topic, source, ...) {
  list(
    formals = get_tensor_method_arguments(topic),
    helpHandler = "torch:::help_handler"
  )
}`

const rtdal009402Source0004 = `help_handler <- function(type, topic, source, ...) {
  if (type == "completion") {
    help_handler_completion(topic, source, ...)
  } else if (type == "parameter") {
    help_handler_parameter(topic, source, ...)
  } else {
    NULL
  }
}`

const rtdal009402Source0005 = `get_tensor_method_arguments <- function(topic) {
  tryCatch(
    rlang::fn_fmls_names(parent.env(Tensor)[[topic]])[-c(1, 2)],
    error = function(e) {
      NULL
    }
  )
}`

const rtdal009402Source0006 = `help_handler_completion <- function(topic, source, ...) {
  signature <- get_tensor_method_arguments(topic)
  signature <- paste0(signature, collapse = ", ")
  signature <- paste0(topic, "(", signature, ")")

  list(title = topic, signature = signature)
}`

const rtdal009402Source0007 = `help_handler_parameter <- function(topic, source, ...) {
  list(
    args = get_tensor_method_arguments(topic)
  )
}`

