const rtdal009409Source0002 = `.DollarNames.torch_ops <- function(x, pattern = "") {
  candidates <- cpp_jit_all_operators()
  if (length(x) == 0) {
    unique(sub("::(.)*", "", candidates))
  } else if (length(x) == 1) {
    if (is.function(x)) return()
    namespace <- x[[1]]
    candidates <- unique(grep(paste0(namespace, "::"), candidates, value = T))
    sub(paste0(namespace, "::"), "", candidates)
  }
}`

const rtdal009409Source0003 = "`$.torch_ops` <- function(x, y, ...) {\n  if (length(x) == 0) {\n    return (structure(list(y), class = \"torch_ops\"))\n  }\n  op <- function(...) {\n    lst <- cpp_jit_execute(paste(x[[1]], y, sep = \"::\"), list(...))\n    if (length(lst) == 1) lst[[1]] else lst \n  }\n  class(op) <- \"torch_ops\"\n  attr(op, \"opname\") <- paste0(x[[1]], \"::\", y)\n  op\n}"

const rtdal009409Source0004 = `print.torch_ops <- function(x, ...) {
  if (length(x) == 1) {
    if (typeof(x) == "closure") {
      opname <- attr(x, "opname")
      info <- cpp_jit_operator_info(opname)
      print(info)
    } else if ((typeof(x) == "list") && typeof(x[[1]]) == "character") {
      cat("<torch_ops>: Handle to namespace ", x[[1]], "\n")
    }
  } else {
    cat("Object of class <torch_ops>\n")
  }
}`

