const rtdal009417Source0002 = "nn_conv_nd <- nn_module(\n  \"nn_conv_nd\",\n  initialize = function(in_channels, out_channels, kernel_size, stride,\n                        padding, dilation, transposed, output_padding,\n                        groups, bias, padding_mode) {\n    if (in_channels %% groups != 0) {\n      value_error(\"`in_channels` must be divisible by groups\")\n    }\n\n    if (out_channels %% groups != 0) {\n      value_error(\"`out_channels` must be divisible by groups\")\n    }\n\n    valid_padding_modes <- c(\"zeros\", \"reflect\", \"replicate\", \"circular\")\n\n    if (!padding_mode %in% valid_padding_modes) {\n      value_error(\n        \"padding_mode must be one of [{paste(valid_padding_modes, collapse = ', ')}],\",\n        \"but got padding_mode='{padding_mode}'.\"\n      )\n    }\n\n    self$in_channels <- in_channels\n    self$out_channels <- out_channels\n    self$kernel_size <- kernel_size\n    self$stride <- stride\n    self$padding <- padding\n    self$dilation <- dilation\n    self$transposed <- transposed\n    self$output_padding <- output_padding\n    self$groups <- groups\n    self$padding_mode <- padding_mode\n\n    # `_reversed_padding_repeated_twice` is the padding to be passed to\n    # `nnf_pad` if needed (e.g., for non-zero padding types that are\n    # implemented as two ops: padding + conv). `nnf_pad` accepts paddings in\n    # reverse order than the dimension.\n    self$reversed_padding_repeated_twice_ <- nn_util_reverse_repeat_tuple(self$padding, 2)\n\n    if (transposed) {\n      self$weight <- nn_parameter(torch_empty(\n        in_channels, out_channels %/% groups, !!!kernel_size\n      ))\n    } else {\n      self$weight <- nn_parameter(torch_empty(\n        out_channels, in_channels %/% groups, !!!kernel_size\n      ))\n    }\n\n    if (bias) {\n      self$bias <- nn_parameter(torch_empty(out_channels))\n    } else {\n      self$register_parameter(\"bias\", NULL)\n    }\n\n    self$reset_parameters()\n  },\n  reset_parameters = function() {\n    nn_init_kaiming_uniform_(self$weight, a = sqrt(5))\n    if (!is.null(self$bias)) {\n      fans <- nn_init_calculate_fan_in_and_fan_out(self$weight)\n      bound <- 1 / sqrt(fans[[1]])\n      nn_init_uniform_(self$bias, -bound, bound)\n    }\n  }\n)"

const rtdal009417Source0003 = `nn_conv1d <- nn_module(
  "nn_conv1d",
  inherit = nn_conv_nd,
  initialize = function(in_channels, out_channels, kernel_size, stride = 1,
                        padding = 0, dilation = 1, groups = 1,
                        bias = TRUE, padding_mode = "zeros") {
    kernel_size <- nn_util_single(kernel_size)
    stride <- nn_util_single(stride)

    if (is.character(padding)) {
      padding <- padding
    } else {
      padding <- nn_util_single(padding)
    }

    dilation <- nn_util_single(dilation)
    super$initialize(
      in_channels, out_channels, kernel_size, stride, padding, dilation,
      FALSE, nn_util_single(0), groups, bias, padding_mode
    )
  },
  forward = function(input) {
    if (self$padding_mode != "zeros") {
      nnf_conv1d(
        nnf_pad(input, self$reversed_padding_repeated_twice_, mode = self$padding_mode),
        self$weight, self$bias, self$stride,
        nn_util_single(0), self$dilation, self$groups
      )
    } else {
      nnf_conv1d(
        input, self$weight, self$bias, self$stride,
        self$padding, self$dilation, self$groups
      )
    }
  }
)`

const rtdal009417Source0004 = `nn_conv2d <- nn_module(
  "nn_conv2d",
  inherit = nn_conv_nd,
  initialize = function(in_channels, out_channels, kernel_size, stride = 1,
                        padding = 0, dilation = 1, groups = 1,
                        bias = TRUE, padding_mode = "zeros") {
    kernel_size <- nn_util_pair(kernel_size)
    stride <- nn_util_pair(stride)

    if (is.character(padding)) {
      padding <- padding
    } else {
      padding <- nn_util_pair(padding)
    }

    dilation <- nn_util_pair(dilation)
    super$initialize(
      in_channels, out_channels, kernel_size, stride, padding, dilation,
      FALSE, nn_util_pair(0), groups, bias, padding_mode
    )
  },
  conv_forward_ = function(input, weight) {
    if (self$padding_mode != "zeros") {
      nnf_conv2d(
        nnf_pad(input, self$reversed_padding_repeated_twice_, mode = self$padding_mode),
        weight, self$bias, self$stride,
        nn_util_pair(0), self$dilation, self$groups
      )
    } else {
      nnf_conv2d(
        input, weight, self$bias, self$stride,
        self$padding, self$dilation, self$groups
      )
    }
  },
  forward = function(input) {
    self$conv_forward_(input, self$weight)
  }
)`

