const rtdal009452Source0031 = `log.torch_tensor <- function(x, base) {
  if (!missing(base)) {
    torch_log(x) / torch_log(base)
  } else {
    torch_log(x)
  }
}`

const rtdal009452Source0046 = `max.torch_tensor <- function(..., na.rm = FALSE) {
  if (na.rm) value_error("Torch tensors do not have NAs!")
  l <- list(...)
  l_max <- lapply(l, torch_max)
  Reduce(function(x, y) torch_max(x, other = y), l_max)
}`

const rtdal009452Source0047 = `min.torch_tensor <- function(..., na.rm = FALSE) {
  if (na.rm) value_error("Torch tensors do not have NAs!")
  l <- list(...)
  l_min <- lapply(l, torch_min)
  Reduce(function(x, y) torch_min(x, other = y), l_min)
}`

const rtdal009452Source0048 = "prod.torch_tensor <- function(..., dim, keepdim = FALSE, na.rm = FALSE) {\n  if (na.rm) value_error(\"Torch tensors do not have NAs!\")\n  l <- list(...)\n  if (length(l) == 1) {\n    if (!missing(dim)) {\n      return(torch_prod(l[[1]], dim = dim, keepdim = keepdim))\n    } else {\n      return(torch_prod(l[[1]]))\n    }\n  } else {\n    stopifnot(missing(dim))\n    return(Reduce(`*`, lapply(l, torch_prod)))\n  }\n}"

const rtdal009452Source0049 = "sum.torch_tensor <- function(..., dim, keepdim = FALSE, na.rm = FALSE) {\n  if (na.rm) value_error(\"Torch tensors do not have NAs!\")\n  l <- list(...)\n  if (length(l) == 1) {\n    if (!missing(dim)) {\n      return(torch_sum(l[[1]], dim = dim, keepdim = keepdim))\n    } else {\n      return(torch_sum(l[[1]]))\n    }\n  } else {\n    stopifnot(missing(dim))\n    return(Reduce(`+`, lapply(l, torch_sum)))\n  }\n}"

const rtdal009452Source0050 = `mean.torch_tensor <- function(x, dim, keepdim = FALSE, na.rm = FALSE, ...) {
  if (na.rm) value_error("Torch tensors do not have NAs!")
  if (!missing(dim)) {
    torch_mean(x, dim, keepdim)
  } else {
    torch_mean(x)
  }
}`

