const rtdal009458Source0002 = `.cubic_interpolate <-
  function(x1, f1, g1, x2, f2, g2, bounds = NULL) {
    # Compute bounds of interpolation area
    if (!is.null(bounds)) {
      xmin_bound <- bounds[1]
      xmax_bound <- bounds[2]
    } else if (x1 <= x2) {
      xmin_bound <- x1
      xmax_bound <- x2
    } else {
      xmin_bound <- x2
      xmax_bound <- x1
    }

    # Code for most common case: cubic interpolation of 2 points
    #   w/ function and derivative values for both
    # Solution in this case (where x2 is the farthest point):
    #   d1 = g1 + g2 - 3*(f1-f2)/(x1-x2);
    #   d2 = sqrt(d1^2 - g1*g2);
    #   min_pos = x2 - (x2 - x1)*((g2 + d2 - d1)/(g2 - g1 + 2*d2));
    #   t_new = min(max(min_pos,xmin_bound),xmax_bound);
    d1 <- g1 + g2 - 3 * (f1 - f2) / (x1 - x2)
    d2_square <- d1^2 - g1 * g2
    if (as.logical(d2_square>= 0)) {
      d2 <- sqrt(d2_square)
      min_pos <- if (x1 <= x2) {
        x2 - (x2 - x1) * ((g2 + d2 - d1) / (g2 - g1 + 2 * d2))
      } else {
        x1 - (x1 - x2) * ((g1 + d2 - d1) / (g1 - g2 + 2 * d2))
      }
      as.numeric(min(max(min_pos, xmin_bound), xmax_bound))
    } else {
      as.numeric((xmin_bound + xmax_bound) / 2)
    }
  }`

const rtdal009458Source0003 = ".strong_wolfe <- function(obj_func,\n                          x,\n                          t,\n                          d,\n                          f,\n                          g,\n                          gtd,\n                          c1 = 1e-4,\n                          c2 = 0.9,\n                          tolerance_change = 1e-9,\n                          max_ls = 25) {\n  d_norm <- d$abs()$max()\n  g <- g$clone(memory_format = torch_contiguous_format())\n  # evaluate objective and gradient using initial step\n  ret <- obj_func(x, t, d)\n  f_new <- ret[[1]]\n  g_new <- ret[[2]]\n  ls_func_evals <- 1\n  gtd_new <- g_new$dot(d)\n\n  # initial phase: find a solution point, or\n  # bracket an initial interval containing a point satisfying the strong Wolfe criteria\n  t_prev <- 0\n  f_prev <- f\n  g_prev <- g\n  gtd_prev <- gtd\n  ls_iter <- 0\n  done <- FALSE\n\n  while (ls_iter < max_ls) {\n    # sufficient decrease (Armijo) condition violated\n    # construct interval between previous (smaller) step size and current\n    if (as.logical(f_new > f + c1 * t * gtd) ||\n      as.logical(ls_iter > 1 && f_new >= f_prev)) {\n      bracket <- c(t_prev, t)\n      bracket_f <- c(f_prev, f_new)\n      bracket_g <- c(g_prev, g_new$clone(memory_format = torch_contiguous_format()))\n      bracket_gtd <- c(gtd_prev, gtd_new)\n      # cat(\"Initial search: sufficient decrease condition violated\", \"\\n\")\n      break\n    }\n\n    # curvature condition satisfied (slope not too steep)\n    # return current parameters, no further zoom stage\n    if (as.logical(abs(gtd_new) <= -c2 * gtd)) {\n      bracket <- c(t)\n      bracket_f <- c(f_new)\n      bracket_g <- c(g_new)\n      done <- TRUE\n      # cat(\"Initial search: strong Wolfe condition satisfied\", \"\\n\")\n      break\n    }\n\n    # curvature condition (strong Wolfe 2) violated (gradient positive)\n    # construct interval between previous (smaller) step size and current\n    if (as.logical(gtd_new >= 0)) {\n      bracket <- c(t_prev, t)\n      bracket_f <- c(f_prev, f_new)\n      bracket_g <- c(g_prev, g_new$clone(memory_format = torch_contiguous_format()))\n      bracket_gtd <- c(gtd_prev, gtd_new)\n      # cat(\"Initial search: curvature condition violated (gradient positive)\", \"\\n\")\n      break\n    }\n\n    # interpolate\n    min_step <- t + 0.01 * (t - t_prev)\n    max_step <- t * 10\n    tmp <- t\n    t <- .cubic_interpolate(t_prev,\n      f_prev,\n      gtd_prev,\n      t,\n      f_new,\n      gtd_new,\n      bounds = c(min_step, max_step)\n    )\n\n    # next step\n    t_prev <- tmp\n    f_prev <- f_new\n    g_prev <- g_new$clone(memory_format = torch_contiguous_format())\n    gtd_prev <- gtd_new\n    ret <- obj_func(x, t, d)\n    f_new <- ret[[1]]\n    g_new <- ret[[2]]\n    ls_func_evals <- ls_func_evals + 1\n    gtd_new <- g_new$dot(d)\n    ls_iter <- ls_iter + 1\n  }\n\n  # reached max number of iterations?\n  if (ls_iter == max_ls) {\n    bracket <- c(0, t)\n    bracket_f <- c(f, f_new)\n    bracket_g <- c(g, g_new)\n  }\n\n  # zoom phase: we now have a point satisfying the criteria, or\n  # a bracket around it. We refine the bracket until we find the\n  # exact point satisfying the criteria\n  insuf_progress <- FALSE\n  # find high and low points in bracket\n  if (bracket_f[[1]] <= bracket_f[[length(bracket_f)]]) {\n    low_pos <- 1\n    high_pos <- 2\n  } else {\n    low_pos <- 2\n    high_pos <- 1\n  }\n\n  while ((done != TRUE) && (ls_iter < max_ls)) {\n    # line-search bracket is so small\n    if (as.logical(abs(bracket[[2]] - bracket[[1]]) * d_norm < tolerance_change)) {\n      # cat(\"Zoom phase: bracket too small\", \"\\n\")\n      break\n    }\n\n\n    # compute new trial value\n    t <-\n      .cubic_interpolate(\n        bracket[[1]],\n        bracket_f[[1]],\n        bracket_gtd[[1]],\n        bracket[[2]],\n        bracket_f[[2]],\n        bracket_gtd[[2]]\n      )\n    # test that we are making sufficient progress:\n    # in case t is too close to boundary, we mark that we are making insufficient progress,\n    # and if we have made insufficient progress in the last step,\n    # or t is at one of the boundaries,\n    # we will move t to a position which is `0.1 * len(bracket)` away from the nearest boundary point.\n    eps <- 0.1 * (max(bracket) - min(bracket))\n    if (min(max(bracket) - t, t - min(bracket)) < eps) {\n      # interpolation close to boundary\n      if ((insuf_progress == TRUE) ||\n        (t >= max(bracket)) || (t <= min(bracket))) {\n        # evaluate at 0.1 away from boundary\n        if (abs(t - max(bracket)) < abs(t - min(bracket))) {\n          t <- max(bracket) - eps\n        } else {\n          t <- min(bracket) + eps\n        }\n        insuf_progress <- FALSE\n      } else {\n        insuf_progress <- TRUE\n      }\n    } else {\n      insuf_progress <- FALSE\n    }\n\n    # Evaluate new point\n    ret <- obj_func(x, t, d)\n    f_new <- ret[[1]]\n    g_new <- ret[[2]]\n    ls_func_evals <- ls_func_evals + 1\n    gtd_new <- g_new$dot(d)\n    ls_iter <- ls_iter + 1\n\n    # Armijo condition violated or not lower than lowest point\n    if (as.logical(f_new > (f + c1 * t * gtd)) ||\n      as.logical(f_new >= bracket_f[[low_pos]])) {\n      # cat(\"Zoom phase: sufficient decrease condition violated\", \"\\n\")\n      bracket[[high_pos]] <- t\n      bracket_f[[high_pos]] <- f_new\n      bracket_g[[high_pos]] <- g_new\n      bracket_gtd[[high_pos]] <- gtd_new\n      if (bracket_f[[1]] <= bracket_f[[2]]) {\n        low_pos <- 1\n        high_pos <- 2\n      } else {\n        low_pos <- 2\n        high_pos <- 1\n      }\n    } else {\n      # Wolfe conditions satisfied\n      if (as.logical(abs(gtd_new) <= -c2 * gtd)) {\n        done <- TRUE\n        # cat(\"Zoom phase: strong Wolfe condition satisfied\", \"\\n\")\n      } else if (as.logical(gtd_new * (bracket[[high_pos]] - bracket[[low_pos]]) >= 0)) {\n        # old high becomes new low\n        bracket[[high_pos]] <- bracket[[low_pos]]\n        bracket_f[[high_pos]] <- bracket_f[[low_pos]]\n        bracket_g[[high_pos]] <- bracket_g[[low_pos]]\n        bracket_gtd[[high_pos]] <- bracket_gtd[[low_pos]]\n      }\n\n      # new point becomes new low\n      bracket[[low_pos]] <- t\n      bracket_f[[low_pos]] <- f_new\n      bracket_g[[low_pos]] <- g_new\n      bracket_gtd[[low_pos]] <- gtd_new\n    }\n  }\n\n  t <- bracket[[low_pos]]\n  f_new <- torch_tensor(bracket_f[[low_pos]])\n  g_new <- bracket_g[[low_pos]]\n  list(f_new, g_new, t, ls_func_evals)\n}"

const rtdal009458Source0004 = `optim_lbfgs <- optimizer(
  "optim_lbfgs",
  initialize = function(params,
                        lr = 1,
                        max_iter = 20,
                        max_eval = NULL,
                        tolerance_grad = 1e-7,
                        tolerance_change = 1e-9,
                        history_size = 100,
                        line_search_fn = NULL) {
    if (is.null(max_eval)) {
      max_eval <- as.integer(max_iter * 5 / 4)
    }

    defaults <- list(
      lr = lr,
      max_iter = max_iter,
      max_eval = max_eval,
      tolerance_grad = tolerance_grad,
      tolerance_change = tolerance_change,
      history_size = history_size,
      line_search_fn = line_search_fn
    )

    super$initialize(params, defaults)

    if (length(self$param_groups) != 1) {
      value_error(
        "LBFGS doesn't support per-parameter options ",
        "(parameter groups)"
      )
    }

    private$.params <- self$param_groups[[1]][["params"]]
    private$.numel_cache <- NULL
  },
  step = function(closure) {
    local_no_grad()

    group <- self$param_groups[[1]]
    lr <- group[["lr"]]
    max_iter <- group[["max_iter"]]
    max_eval <- group[["max_eval"]]
    tolerance_grad <- group[["tolerance_grad"]]
    tolerance_change <- group[["tolerance_change"]]
    line_search_fn <- group[["line_search_fn"]]
    history_size <- group[["history_size"]]

    # NOTE: LBFGS has only global state, but we register it as state for
    # the first param, because this helps with casting in load_state_dict
    if (is.null(state(private$.params[[1]]))) {
      state(private$.params[[1]]) <- new.env(parent = emptyenv())
      state(private$.params[[1]])[["func_evals"]] <- 0
      state(private$.params[[1]])[["n_iter"]] <- 0
    }
    state <- state(private$.params[[1]])

    # evaluate initial f(x) and df/dx
    with_enable_grad({
      orig_loss <- closure()
    })

    current_evals <- 1
    state[["func_evals"]] <- state[["func_evals"]] + 1

    flat_grad <- private$.gather_flat_grad()
    opt_cond <- (flat_grad$abs()$max() <= tolerance_grad)$item()

    if (opt_cond) {
      return(orig_loss)
    }
    loss <- orig_loss$item()

    # tensors cached in state (for tracing)
    d <- state[["d"]]
    t <- state[["t"]]
    old_dirs <- state[["old_dirs"]]
    old_stps <- state[["old_stps"]]
    ro <- state[["ro"]]
    H_diag <- state[["H_diag"]]
    prev_flat_grad <- state[["prev_flat_grad"]]
    prev_loss <- state[["prev_loss"]]

    n_iter <- 0
    # optimize for a max of max_iter iterations
    while (n_iter < max_iter) {
      # keep track of nb of iterations
      n_iter <- n_iter + 1
      state[["n_iter"]] <- state[["n_iter"]] + 1

      ############################################################
      # compute gradient descent direction
      ############################################################

      if (state[["n_iter"]] == 1) {
        d <- flat_grad$neg()
        old_dirs <- list()
        old_stps <- list()
        ro <- list()
        H_diag <- 1
      } else {
        # do lbfgs update (update memory)
        y <- flat_grad$sub(prev_flat_grad)
        s <- d$mul(t)
        ys <- y$dot(s) # y*s

        ys_it <- ys$item()
        if (!is.na(ys_it) && ys_it > 1e-10) {
          # updating memory
          if (length(old_dirs) == history_size) {
            # shift history by one (limited-memory)
            old_dirs <- old_dirs[-1]
            old_stps <- old_stps[-1]
            ro <- ro[-1]
          }

          # store new direction/step
          old_dirs[[length(old_dirs) + 1]] <- y
          old_stps[[length(old_stps) + 1]] <- s
          ro[[length(ro) + 1]] <- 1. / ys

          # update scale of initial Hessian approximation
          H_diag <- ys / y$dot(y) # (y*y)
        }

        # compute the approximate (L-BFGS) inverse Hessian
        # multiplied by the gradient
        num_old <- length(old_dirs)

        if (is.null(state[["al"]])) {
          state[["al"]] <- vector(mode = "list", length = history_size)
        }

        al <- state[["al"]]

        # iteration in L-BFGS loop collapsed to use just one buffer
        q <- flat_grad$neg()
        if (num_old >= 1) {
          for (i in seq(num_old, 1, by = -1)) {
            al[[i]] <- old_stps[[i]]$dot(q) * ro[[i]]
            q$add_(old_dirs[[i]], alpha = -al[[i]])
          }
        }

        # multiply by initial Hessian
        # r/d is the final direction
        d <- r <- torch_mul(q, H_diag)
        for (i in seq_len(num_old)) {
          be_i <- old_dirs[[i]]$dot(r) * ro[[i]]
          r$add_(old_stps[[i]], alpha = al[[i]] - be_i)
        }
      }

      if (is.null(prev_flat_grad) || is_undefined_tensor(prev_flat_grad)) {
        prev_flat_grad <- flat_grad$clone(memory_format = torch_contiguous_format())
      } else {
        prev_flat_grad$copy_(flat_grad)
      }
      prev_loss <- loss

      ############################################################
      # compute step length
      ############################################################
      # reset initial guess for step size
      if (state[["n_iter"]] == 1) {
        t <- min(1., 1. / flat_grad$abs()$sum()$item()) * lr
      } else {
        t <- lr
      }

      # directional derivative
      gtd <- flat_grad$dot(d) # g * d
      gtd_it <- gtd$item()

      # directional derivative is below tolerance
      if (!is.na(gtd_it) && gtd_it > (-tolerance_change)) {
        break
      }

      # optional line search: user function
      ls_func_evals <- 0

      if (!is.null(line_search_fn)) {
        if (line_search_fn != "strong_wolfe") {
          value_error("only strong_wolfe is supported")
        } else {
          x_init <- private$.clone_param()

          obj_func <- function(x, t, d) {
            private$.directional_evaluate(closure, x, t, d)
          }

          ret <- .strong_wolfe(obj_func, x_init, t, d, prev_loss, flat_grad, gtd)

          loss <- ret[[1]]$item()
          flat_grad <- ret[[2]]
          t <- ret[[3]]
          ls_func_evals <- ret[[4]]

          private$.add_grad(t, d)
          opt_cond <- flat_grad$abs()$max()$item() <= tolerance_grad
        }
      } else {
        # no line search, simply move with fixed-step
        private$.add_grad(t, d)
        if (n_iter != max_iter) {
          # re-evaluate function only if not in last iteration
          # the reason we do this: in a stochastic setting,
          # no use to re-evaluate that function here
          with_enable_grad({
            loss <- closure()$item()
          })
          flat_grad <- private$.gather_flat_grad()
          opt_cond <- flat_grad$abs()$max()$item() <= tolerance_grad
          ls_func_evals <- 1
        }
      }

      # update func eval
      current_evals <- current_evals + ls_func_evals
      state[["func_evals"]] <- state[["func_evals"]] + ls_func_evals

      ############################################################
      # check conditions
      ############################################################
      if (n_iter == max_iter) {
        break
      }

      if (current_evals >= max_eval) {
        break
      }

      # optimal condition
      if (!is.na(opt_cond) && opt_cond) {
        break
      }

      # lack of progress
      d_ml <- d$mul(t)$abs()$max()$item()
      if (!is.na(d_ml) && d_ml <= tolerance_change) {
        break
      }

      if (!is.na(loss) && abs(loss - prev_loss) < tolerance_change) {
        break
      }
    }

    state[["d"]] <- d
    state[["t"]] <- t
    state[["old_dirs"]] <- old_dirs
    state[["old_stps"]] <- old_stps
    state[["ro"]] <- ro
    state[["H_diag"]] <- H_diag
    state[["prev_flat_grad"]] <- prev_flat_grad
    state[["prev_loss"]] <- prev_loss

    orig_loss
  },
  private = list(
    .numel = function() {
      if (is.null(private$.numel_cache)) {
        private$.numel_cache <- sum(sapply(private$.params, function(p) p$numel()))
      }
      private$._numel_cache
    },
    .gather_flat_grad = function() {
      views <- list()
      for (i in seq_along(private$.params)) {
        p <- private$.params[[i]]
        if (is_undefined_tensor(p$grad)) {
          view <- .new_zeros_tensor(p)
        } else {
          view <- p$grad$view(-1)
        }
        views[[i]] <- view
      }
      torch_cat(views, dim = 1)
    },
    .add_grad = function(step_size, update) {
      offset <- 1
      for (p in private$.params) {
        numel <- p$numel()
        p$add_(update[offset:(offset + numel - 1)]$view_as(p), alpha = step_size)
        offset <- offset + numel
      }
      stopifnot(offset == private$.numel())
    },
    .clone_param = function() {
      lapply(private$.params, function(p) p$clone(memory_format = torch_contiguous_format()))
    },
    .set_param = function(params_data) {
      for (i in seq_along(private$.params)) {
        private$.params[[i]]$copy_(params_data[[i]])
      }
    },
    .directional_evaluate = function(closure, x, t, d) {
      private$.add_grad(t, d)
      with_enable_grad({
        loss <- closure()$item()
      })
      flat_grad <- private$.gather_flat_grad()
      private$.set_param(x)
      list(loss, flat_grad)
    }
  )
)`

const rtdal009458Source0005 = `.new_zeros_tensor <- function(p) {
  torch_zeros(p$numel(), dtype = p$dtype, device = p$device)
}`

