const rtdal009459Source0003 = `LRScheduler <- R6::R6Class(
  "LRScheduler",
  lock_objects = FALSE,
  public = list(
    initialize = function(optimizer, last_epoch = -1, verbose = FALSE) {
      if (!is_optimizer(optimizer)) {
        type_error("not an optimizer")
      }

      self$optimizer <- optimizer

      if (last_epoch == -1) {
        optimizer$param_groups <- lapply(
          optimizer$param_groups,
          function(group) {
            setdefault(group, "initial_lr", group[["lr"]])
          }
        )
      } else {
        lapply(
          optimizer$param_groups,
          function(group) {
            if (is.null(group[["initial_lr"]])) {
              value_error("param 'inital_lr' is not specified.")
            }
          }
        )
      }

      self$base_lrs <- lapply(
        optimizer$param_groups,
        function(group) group[["initial_lr"]]
      )

      self$last_epoch <- last_epoch
      self$verbose <- verbose
      
      self$.step_count <- 0L
      self$step()
    },
    state_dict = function() {
      dict <- as.list(self)
      dict <- dict[-which(names(dict) == "optimizer")]
      
      # we also drop functions and environments
      dict <- dict[!sapply(dict, is.function)]
      dict <- dict[!sapply(dict, is.environment)]
      
      dict
    },
    load_state_dict = function(state_dict) {
      for (nm in names(state_dict)) {
        self[[nm]] <- state_dict[[nm]]
      }
    },
    get_last_lr = function() {
      self$.last_lr
    },
    get_lr = function() {
      not_implemented_error()
    },
    print_lr = function(is_verbose, group, lr) {
      if (is_verbose) {
        inform(sprintf("Adjusting learning rate of group %s to %.4f", group, lr))
      }
    },
    step = function() {
      self$.step_count <- self$.step_count + 1L
      self$last_epoch <- self$last_epoch + 1
      values <- self$get_lr()

      for (i in seq_along(self$optimizer$param_groups)) {
        self$optimizer$param_groups[[i]]$lr <- values[[i]]
        self$print_lr(self$verbose, i, self$optimizer$param_groups[[i]]$lr)
      }

      self$.last_lr <- sapply(self$optimizer$param_groups, function(x) x$lr)
    }
  )
)`

const rtdal009459Source0004 = `lr_scheduler <- function(classname = NULL, inherit = LRScheduler, ...,
                         parent_env = parent.frame()) {
  if (inherits(inherit, "lr_scheduler")) {
    inherit <- attr(inherit, "scheduler")
  }

  e <- new.env(parent = parent_env)
  e$inherit <- inherit

  classes <- c(classname, "lr_scheduler")

  Scheduler <- R6::R6Class(
    classname = classname,
    inherit = inherit,
    lock_objects = FALSE,
    public = list(
      .classes = classes,
      ...
    ),
    parent_env = e
  )

  init <- get_init(Scheduler)
  fun <- rlang::new_function(
    args = rlang::fn_fmls(init),
    body = rlang::expr({
      instance <- Scheduler$new(!!!rlang::fn_fmls_syms(init))
      instance
    })
  )

  attr(fun, "class") <- c(classes, "lr_scheduler_generator")
  attr(fun, "scheduler") <- Scheduler
  fun
}`

const rtdal009459Source0005 = `lr_lambda <- lr_scheduler(
  "lr_lambda",
  initialize = function(optimizer, lr_lambda, last_epoch = -1, verbose = FALSE) {
    self$optimizer <- optimizer

    if (!is.list(lr_lambda)) {
      self$lr_lambdas <- lapply(
        seq_along(optimizer$param_groups),
        function(i) lr_lambda
      )
    } else {
      if (length(lr_lambda) != length(optimizer$param_groups)) {
        i <- length(lr_lambda)
        j <- length(optimizer$param_groups)
        value_error(
          "lr_lambda length ({i}) is different from the number of",
          "optimizer$param_grpups ({j})"
        )
      }

      self$lr_lambdas <- lr_lambda
    }

    super$initialize(optimizer, last_epoch, verbose)
  },
  get_lr = function() {
    lrs <- as.numeric(self$base_lrs)
    for (i in seq_along(lrs)) {
      lrs[i] <- lrs[i] * self$lr_lambdas[[i]](self$last_epoch)
    }

    lrs
  }
)`

const rtdal009459Source0006 = `lr_multiplicative <- lr_scheduler(
  "lr_multiplicative",
  initialize = function(optimizer, lr_lambda, last_epoch = -1, verbose = FALSE) {
    self$optimizer <- optimizer

    if (!is.list(lr_lambda)) {
      self$lr_lambdas <- lapply(
        seq_along(optimizer$param_groups),
        function(i) lr_lambda
      )
    } else {
      if (length(lr_lambda) != length(optimizer$param_groups)) {
        i <- length(lr_lambda)
        j <- length(optimizer$param_groups)
        value_error(
          "lr_lambda length ({i}) is different from the number of",
          "optimizer$param_grpups ({j})"
        )
      }

      self$lr_lambdas <- lr_lambda
    }

    super$initialize(optimizer, last_epoch, verbose)
  },
  get_lr = function() {
    if (self$last_epoch > 0) {
      lrs <- numeric(length = length(self$optimizer$param_groups))
      for (i in seq_along(self$optimizer$param_groups)) {
        lrs[i] <- self$optimizer$param_groups[[i]]$lr * self$lr_lambdas[[i]](self$last_epoch)
      }
    } else {
      lrs <- as.numeric(self$base_lrs)
    }
    lrs
  }
)`

const rtdal009459Source0007 = `lr_step <- lr_scheduler(
  "lr_step",
  initialize = function(optimizer, step_size, gamma = 0.1, last_epoch = -1) {
    self$step_size <- step_size
    self$gamma <- gamma
    super$initialize(optimizer, last_epoch)
  },
  get_lr = function() {
    if ((self$last_epoch == 0) || (self$last_epoch %% self$step_size != 0)) {
      return(sapply(self$optimizer$param_groups, function(x) x$lr))
    }

    sapply(self$optimizer$param_groups, function(x) x$lr * self$gamma)
  }
)`

const rtdal009459Source0008 = "lr_one_cycle <- lr_scheduler(\n  \"lr_one_cycle\",\n  initialize = function(optimizer,\n                        max_lr,\n                        total_steps = NULL,\n                        epochs = NULL,\n                        steps_per_epoch = NULL,\n                        pct_start = 0.3,\n                        anneal_strategy = \"cos\",\n                        cycle_momentum = TRUE,\n                        base_momentum = 0.85,\n                        max_momentum = 0.95,\n                        div_factor = 25.,\n                        final_div_factor = 1e4,\n                        last_epoch = -1,\n                        verbose = FALSE) {\n    self$optimizer <- optimizer\n\n    # Validate total_steps\n    if (is.null(total_steps) && is.null(epochs) && is.null(steps_per_epoch)) {\n      value_error(\"You must define either total_steps OR (epochs AND steps_per_epoch)\")\n    } else if (!is.null(total_steps)) {\n      if (!is.numeric(total_steps) || total_steps <= 0) {\n        value_error(\"Expected positive integer total_steps, but got {total_steps}\")\n      }\n\n      self$total_steps <- total_steps\n    } else {\n      if (!is.numeric(epochs) || epochs <= 0) {\n        value_error(\"Expected positive integer epochs, but got {epochs}\")\n      }\n\n      if (!is.numeric(steps_per_epoch) || steps_per_epoch <= 0) {\n        value_error(\"Expected positive integer steps_per_epoch, but got {steps_per_epoch}\")\n      }\n\n      self$total_steps <- epochs * steps_per_epoch\n    }\n\n    self$step_size_up <- (pct_start * self$total_steps) - 1\n    self$step_size_down <- (self$total_steps - self$step_size_up) - 1\n\n    # Validate pct_start\n    if (!is.numeric(pct_start) || pct_start < 0 || pct_start > 1) {\n      value_error(\"Expected float between 0 and 1 pct_start, but got {pct_start}\")\n    }\n\n    # Validate anneal_strategy\n    if (!anneal_strategy %in% c(\"cos\", \"linear\")) {\n      value_error(\"anneal_strategy must by one of 'cos' or 'linear', instead got {anneal_strategy}\")\n    } else if (anneal_strategy == \"cos\") {\n      self$anneal_func <- self$.annealing_cos\n    } else if (anneal_strategy == \"linear\") {\n      self.anneal_func <- self$.annealing_linear\n    }\n\n    # Initialize learning rate variables\n    max_lrs <- self$.format_param(\"max_lr\", self$optimizer, max_lr)\n    if (last_epoch == -1) {\n      for (i in seq_along(self$optimizer$param_groups)) {\n        self$optimizer$param_groups[[i]][[\"initial_lr\"]] <- max_lrs[[i]] / div_factor\n        self$optimizer$param_groups[[i]][[\"max_lr\"]] <- max_lrs[[i]]\n        self$optimizer$param_groups[[i]][[\"min_lr\"]] <- self$optimizer$param_groups[[i]][[\"initial_lr\"]] /\n          final_div_factor\n      }\n    }\n\n    # Initialize momentum variables\n    self$cycle_momentum <- cycle_momentum\n\n    if (self$cycle_momentum) {\n      if ((!\"momentum\" %in% names(self$optimizer$defaults)) &&\n        !(\"betas\" %in% names(self$optimizer$defaults))) {\n        value_error(\"optimizer must support momentum with `cycle momentum` enabled\")\n      }\n\n      self$use_beta1 <- \"betas\" %in% names(self$optimizer$defaults)\n      max_momentums <- self$.format_param(\"max_momentum\", optimizer, max_momentum)\n      base_momentums <- self$.format_param(\"base_momentum\", optimizer, base_momentum)\n\n      if (last_epoch == -1) {\n        for (i in seq_along(self$optimizer$param_groups)) {\n          if (self$use_beta1) {\n            beta2 <- self$optimizer$param_groups[[i]]$betas[[2]]\n            self$optimizer$param_groups[[i]]$betas <- c(max_momentum[[i]], beta2)\n          } else {\n            self$optimizer$param_groups[[i]]$momentum <- max_momentum[[i]]\n          }\n\n          self$optimizer$param_groups[[i]]$max_momentum <- max_momentum[[i]]\n          self$optimizer$param_groups[[i]]$base_momentum <- base_momentums[[i]]\n        }\n      }\n    }\n\n    super$initialize(optimizer, last_epoch, verbose)\n  },\n  .format_param = function(name, optimizer, param) {\n    if (is.list(param) || length(param) > 1) {\n      if (length(param) != length(optimizer$param_groups)) {\n        value_error(\n          \"expected {length(optimizer$param_groups)} values for {name}\",\n          \"but got {length(param)}\"\n        )\n      }\n\n      return(param)\n    } else {\n      return(lapply(seq_along(optimizer$param_groups), function(x) param))\n    }\n  },\n  .annealing_cos = function(start, end, pct) {\n    cos_out <- cos(pi * pct) + 1\n    end + (start - end) / 2.0 * cos_out\n  },\n  .annealing_linear = function(start, end, pct) {\n    (end - start) * pct + start\n  },\n  get_lr = function() {\n    lrs <- list()\n    step_num <- self$last_epoch\n\n    if (step_num > self$total_steps) {\n      value_error(\n        \"Tried to step {step_num+1} times. The specified number of total steps is {self$total_steps}\"\n      )\n    }\n\n    for (i in seq_along(self$optimizer$param_groups)) {\n      if (step_num <= self$step_size_up) {\n        computed_lr <- self$anneal_func(\n          self$optimizer$param_groups[[i]][[\"initial_lr\"]],\n          self$optimizer$param_groups[[i]][[\"max_lr\"]],\n          step_num / self$step_size_up\n        )\n\n        if (self$cycle_momentum) {\n          computed_momentum <- self$anneal_func(\n            self$optimizer$param_groups[[i]][[\"max_momentum\"]],\n            self$optimizer$param_groups[[i]][[\"base_momentum\"]],\n            step_num / self$step_size_up\n          )\n        }\n      } else {\n        down_step_num <- step_num - self$step_size_up\n        computed_lr <- self$anneal_func(\n          self$optimizer$param_groups[[i]][[\"max_lr\"]],\n          self$optimizer$param_groups[[i]][[\"min_lr\"]],\n          down_step_num / self$step_size_down\n        )\n\n        if (self$cycle_momentum) {\n          computed_momentum <- self$anneal_func(\n            self$optimizer$param_groups[[i]][[\"base_momentum\"]],\n            self$optimizer$param_groups[[i]][[\"max_momentum\"]],\n            down_step_num / self$step_size_down\n          )\n        }\n      }\n\n      lrs[[i]] <- computed_lr\n      if (self$cycle_momentum) {\n        if (self$use_beta1) {\n          beta2 <- self$optimizer$param_groups[[i]][[\"betas\"]][[2]]\n          self$optimizer$param_groups[[i]][[\"betas\"]] <- c(computed_momentum, beta2)\n        } else {\n          self$optimizer$param_groups[[i]][[\"momentum\"]] <- computed_momentum\n        }\n      }\n    }\n\n    as.numeric(lrs)\n  }\n)"

const rtdal009459Source0009 = `lr_reduce_on_plateau <- lr_scheduler(
  "lr_reduce_on_plateau",
  initialize = function(optimizer, mode='min', factor=0.1, patience=10,
                         threshold=1e-4, threshold_mode='rel', cooldown=0,
                         min_lr=0, eps=1e-8, verbose=FALSE) {
    if (factor>=1.0) {
      value_error('Factor should be < 1.0')
    }
    self$factor <- factor
    self$optimizer <- optimizer
    
    if (is.list(min_lr)) {
      if (length(min_lr) != length(optimizer$param_groups)) {
        value_error("expected {length(optimizer$param_groups} min_lrs, got {length(min_lr)}")
      }
      self$min_lrs <- list(min_lr)
    }
    else {
      self$min_lrs <- rep(list(min_lr), length(optimizer$param_groups))
    }
    self$patience <- patience
    self$verbose <- verbose
    self$cooldown <- cooldown
    self$cooldown_counter <- 0
    self$mode <- mode
    self$threshold <- threshold
    self$threshold_mode <- threshold_mode
    self$best <- NULL
    self$num_bad_epochs <- NULL
    self$mode_worse <- NULL
    self$eps <- eps
    self$last_epoch <- 0
    
    self$.init_is_better(mode=mode, threshold=threshold, 
                         threshold_mode=threshold_mode)
    self$.reset()
    
  },
  step = function(metrics) {
    current <- as.numeric(metrics)
    epoch <- self$last_epoch + 1
    self$last_epoch <- epoch
    
    if (self$.is_better(current, self$best)) {
      self$best <- current
      self$num_bad_epochs <- 0
    } else {
      self$num_bad_epochs <- self$num_bad_epochs + 1
    }
    
    if (self$.in_cooldown()) {
      self$cooldown_counter <- self$cooldown_counter - 1
      self$num_bad_epochs <- 0
    }
    
    if (self$num_bad_epochs > self$patience) {
      self$.reduce_lr(epoch)
      self$cooldown_counter <- self$cooldown
      self$num_bad_epochs <- 0
    }
    
    self$.last_lr <- sapply(self$optimizer$param_groups, function(x) x$lr)
    
  },
  .reduce_lr = function(epoch) {
    for (i in seq_along(self$optimizer$param_groups)) {
      old_lr <- as.numeric(self$optimizer$param_groups[[i]]$lr)
      new_lr <- max(old_lr * self$factor, self$min_lrs[[i]])
      if ((old_lr - new_lr) > self$eps) {
        self$optimizer$param_groups[[i]]$lr <- new_lr
        if (self$verbose) {
          inform(sprintf("Epoch %s: reducing learning rate of group %s to %.4e", epoch, i, new_lr))
        }
      }
      
    }
  }, 
  .in_cooldown = function() {
    return(self$cooldown_counter > 0)
  },
  .is_better = function(a, best) {
    if ((self$mode == 'min') && (self$threshold_mode == 'rel')) {
      rel_epsilon <- 1 - self$threshold
      return(a < (best * rel_epsilon))
    } else if ((self$mode == 'min') && (self$threshold_mode == 'abs')) {
      return(a < (best - self$threshold))
    } else if ((self$mode == 'max') && (self$threshold_mode == 'rel')) {
      rel_epsilon <- self$threshold  + 1
      return (a > (best * rel_epsilon))
    } else {
      return (a > (best + self$threshold))
    }
  },
  .init_is_better = function(mode, threshold, threshold_mode) {
    if (!mode %in% list('min', 'max')) {
      value_error("mode {mode} is unknown!")
    }
    if (!threshold_mode %in% list('rel', 'abs')) {
      value_error("threshold mode {threshold_mode} is unknown!")
    }
    if (mode == 'min') {
      self$mode_worse <- Inf
    } else {
      self$mode_worse <- -Inf
    }
    
    self$mode <- mode
    self$threshold <- threshold
    self$threshold_mode <- threshold_mode
  },
  .reset = function() {
    self$best <- self$mode_worse
    self$cooldown_counter <- 0
    self$num_bad_epochs <- 0
  }
  
)`

const rtdal009459Source0010 = `lr_cosine_annealing <- lr_scheduler(
  "lr_cosine_annealing",
  initialize = function(optimizer, T_max, eta_min=0, last_epoch=-1, verbose=FALSE) {
    self$T_max <- T_max
    self$eta_min <- eta_min
    super$initialize(optimizer, last_epoch, verbose)
  },
  get_lr = function() {
    if (self$last_epoch == 0) {
      return(lapply(self$optimizer$param_groups, function(x) x[["lr"]]))
    } else if (self$.step_count == 1 && self$last_epoch > 0) {
      lapply(self$base_lrs, function(group, base_lr) {
        self$eta_min + 
          (base_lr - self$eta_min) * 
          (1 + cos(self$last_epoch * pi / self$T_max)) / 
          2  
      })
    } else if ((self$last_epoch -1 - self$T_max) %% (2 * self$T_max) == 0) {
      map2(self$optimizer$param_groups, self$base_lrs, function(group, base_lr) {
        group[["lr"]] + (base_lr - self$eta_min) * (1 - cos(pi / self$T_max)) / 2
      })
    } else {
      lapply(self$optimizer$param_groups, function(group) {
        (1 + cos(pi * self$last_epoch / self$T_max)) /
          (1 + cos(pi * (self$last_epoch - 1) / self$T_max)) *
          (group[['lr']] - self$eta_min) + self$eta_min
      })
    }
  }
)`

